\title{Scaling Quantum Optimization to the Thousand-Qubit Scale with Distributed Quantum Sampling}

\author{Amana Liaqat}
\affiliation{Qoro Quantum Ltd., United Kingdom}

\author{Ahmed Darwish}
\affiliation{Qoro Quantum GmbH, Germany}

\author{Stephen DiAdamo}
\email{stephen@qoroquantum.de}
\affiliation{Qoro Quantum GmbH, Germany}

\author{Dan Holme}
\affiliation{Qoro Quantum Ltd., United Kingdom}

\author{Kieran McDowall}
\affiliation{National Quantum Computing Centre, United Kingdom}
