\title{Quantum Magic  and the Strong Coupling Constant}

\author{ Qiaofeng Liu$^{\, a}$, Ian Low$^{\, a,b}$, Zhewei Yin$^{\, c}$}

\affiliation{\vspace{0.1cm}
\mbox{$^a$ Department of Physics and Astronomy, Northwestern University, Evanston, IL 60208, USA}\\ 
